def macro(title,spell,note,code=None):
    return dict(title=title,spell=spell,note=note,code=code or f'#showtooltip {spell}\n/cast {spell}')
def enemy(title,spell,note='',stop=False):
    code=f'#showtooltip {spell}\n'+('/stopcasting\n' if stop else '')+f'/cast [mod:shift,@focus,harm,nodead][nomod,@mouseover,harm,nodead][nomod,harm,nodead] {spell}'
    return macro(title,spell,'Normal: enemigo bajo el ratón o tu objetivo. Shift: foco enemigo vivo, sin alternativa si no hay foco válido. '+note,code)
def friend(title,spell,note=''):
    return macro(title,spell,'Alt: tú. Normal: aliado vivo bajo el ratón, aliado seleccionado o tú. Conserva tu objetivo de daño al usar marcos de grupo. '+note,f'#showtooltip {spell}\n/cast [mod:alt,@player][@mouseover,help,nodead][help,nodead][@player] {spell}')
